CREATE TABLE IF NOT EXISTS admins(id SERIAL PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'super_admin',active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW(),last_login_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(key VARCHAR(150) PRIMARY KEY,value TEXT,updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,parent_id INT REFERENCES categories(id) ON DELETE CASCADE,name VARCHAR(255) NOT NULL,slug VARCHAR(255) UNIQUE NOT NULL,section VARCHAR(40) NOT NULL DEFAULT 'science',active BOOLEAN DEFAULT TRUE,sort_order INT DEFAULT 0,description TEXT,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS authors(id SERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,full_name VARCHAR(500),birth_year VARCHAR(100),death_year VARCHAR(100),location VARCHAR(255),biography TEXT,teachers TEXT,students TEXT,works TEXT,aliases TEXT,photo_path TEXT,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS author_aliases(id SERIAL PRIMARY KEY,author_id INT REFERENCES authors(id) ON DELETE CASCADE,alias VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS author_relations(id SERIAL PRIMARY KEY,author_id INT REFERENCES authors(id) ON DELETE CASCADE,related_author_id INT REFERENCES authors(id) ON DELETE CASCADE,relation_type VARCHAR(80) NOT NULL,UNIQUE(author_id,related_author_id,relation_type));
CREATE TABLE IF NOT EXISTS resources(id BIGSERIAL PRIMARY KEY,type VARCHAR(40) NOT NULL DEFAULT 'book',slug VARCHAR(500) UNIQUE,language_code VARCHAR(20) DEFAULT 'fa',status VARCHAR(30) DEFAULT 'published',created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS resource_translations(id BIGSERIAL PRIMARY KEY,resource_id BIGINT REFERENCES resources(id) ON DELETE CASCADE,language_code VARCHAR(20) NOT NULL,title VARCHAR(500),short_description TEXT,full_description TEXT,UNIQUE(resource_id,language_code));
CREATE TABLE IF NOT EXISTS books(id SERIAL PRIMARY KEY,resource_id BIGINT UNIQUE REFERENCES resources(id) ON DELETE SET NULL,title VARCHAR(500) NOT NULL,slug VARCHAR(500) UNIQUE,author_id INT REFERENCES authors(id) ON DELETE SET NULL,language_code VARCHAR(20) DEFAULT 'fa',translator VARCHAR(255),pages INT,volumes INT DEFAULT 1,publication_year VARCHAR(100),publisher VARCHAR(255),source_name VARCHAR(255),source_url TEXT,description TEXT,full_description TEXT,keywords TEXT,cover_path TEXT,status VARCHAR(30) DEFAULT 'published',featured BOOLEAN DEFAULT FALSE,featured_order INT DEFAULT 0,admin_order INT DEFAULT 0,is_my_book BOOLEAN DEFAULT FALSE,show_downloads BOOLEAN DEFAULT TRUE,views BIGINT DEFAULT 0,downloads BIGINT DEFAULT 0,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS book_volumes(id SERIAL PRIMARY KEY,book_id INT REFERENCES books(id) ON DELETE CASCADE,volume_no INT NOT NULL,volume_title VARCHAR(500),pages INT,file_path TEXT,external_url TEXT,source_name VARCHAR(255),file_size BIGINT,downloads BIGINT DEFAULT 0,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW(),UNIQUE(book_id,volume_no));
CREATE TABLE IF NOT EXISTS book_categories(book_id INT REFERENCES books(id) ON DELETE CASCADE,category_id INT REFERENCES categories(id) ON DELETE CASCADE,PRIMARY KEY(book_id,category_id));
CREATE TABLE IF NOT EXISTS book_tags(book_id INT REFERENCES books(id) ON DELETE CASCADE,tag VARCHAR(120) NOT NULL,PRIMARY KEY(book_id,tag));
CREATE TABLE IF NOT EXISTS book_relations(book_id INT REFERENCES books(id) ON DELETE CASCADE,related_book_id INT REFERENCES books(id) ON DELETE CASCADE,relation_type VARCHAR(50) NOT NULL,PRIMARY KEY(book_id,related_book_id,relation_type));
CREATE TABLE IF NOT EXISTS submissions(id SERIAL PRIMARY KEY,submitter_name VARCHAR(255),email VARCHAR(255),phone VARCHAR(100),book_title VARCHAR(500),author_name VARCHAR(500),category_ids TEXT,subject VARCHAR(255),description TEXT,language_code VARCHAR(20),publication_year VARCHAR(100),source_name VARCHAR(255),copyright_status VARCHAR(80),file_path TEXT,cover_path TEXT,external_url TEXT,status VARCHAR(30) DEFAULT 'pending',admin_note TEXT,tracking_token VARCHAR(100) UNIQUE,edit_token VARCHAR(100) UNIQUE,final_approved_at TIMESTAMP,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS submission_events(id BIGSERIAL PRIMARY KEY,submission_id INT REFERENCES submissions(id) ON DELETE CASCADE,event_type VARCHAR(80),message TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS feedback(id SERIAL PRIMARY KEY,name VARCHAR(255),email VARCHAR(255),message TEXT NOT NULL,approved BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS featured_books(book_id INT PRIMARY KEY REFERENCES books(id) ON DELETE CASCADE,sort_order INT DEFAULT 0,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS related_sites(id SERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,description TEXT,url TEXT NOT NULL,active BOOLEAN DEFAULT TRUE,sort_order INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS activity_logs(id BIGSERIAL PRIMARY KEY,admin_id INT REFERENCES admins(id) ON DELETE SET NULL,action VARCHAR(100),entity_type VARCHAR(100),entity_id INT,details TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS resource_versions(id BIGSERIAL PRIMARY KEY,resource_type VARCHAR(50),resource_id BIGINT,version_no INT,editor_id INT REFERENCES admins(id) ON DELETE SET NULL,snapshot JSONB,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS visits(id BIGSERIAL PRIMARY KEY,resource_type VARCHAR(50),resource_id BIGINT,ip_hash VARCHAR(128),user_agent TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS downloads(id BIGSERIAL PRIMARY KEY,book_id INT REFERENCES books(id) ON DELETE SET NULL,volume_id INT REFERENCES book_volumes(id) ON DELETE SET NULL,ip_hash VARCHAR(128),created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS password_resets(id BIGSERIAL PRIMARY KEY,admin_id INT REFERENCES admins(id) ON DELETE CASCADE,token_hash VARCHAR(128) UNIQUE NOT NULL,expires_at TIMESTAMP NOT NULL,used_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS collections(id SERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,slug VARCHAR(255) UNIQUE NOT NULL,description TEXT,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS collection_books(collection_id INT REFERENCES collections(id) ON DELETE CASCADE,book_id INT REFERENCES books(id) ON DELETE CASCADE,sort_order INT DEFAULT 0,PRIMARY KEY(collection_id,book_id));
CREATE TABLE IF NOT EXISTS external_sources(id SERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,url TEXT NOT NULL,topic VARCHAR(255),language_code VARCHAR(20),rights_note TEXT,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_books_status ON books(status); CREATE INDEX IF NOT EXISTS idx_books_views ON books(views DESC); CREATE INDEX IF NOT EXISTS idx_books_updated ON books(updated_at DESC); CREATE INDEX IF NOT EXISTS idx_categories_parent ON categories(parent_id); CREATE INDEX IF NOT EXISTS idx_books_title ON books(title); CREATE INDEX IF NOT EXISTS idx_visits_resource ON visits(resource_type,resource_id); CREATE INDEX IF NOT EXISTS idx_downloads_book ON downloads(book_id); CREATE INDEX IF NOT EXISTS idx_submission_status ON submissions(status);
